function marketDrawLine(ctx,a,box,color,alpha=1,progress=1){const points=a.points,returns=points.map(p=>p[1]/a.previous-1),lo=Math.min(0,...returns),hi=Math.max(0,...returns),pad=Math.max(.0015,(hi-lo)*.16),min=lo-pad,max=hi+pad,first=marketMinutes(points[0][0]),last=marketMinutes(points.at(-1)[0]),X=i=>box.x+(marketMinutes(points[i][0])-first)/(last-first||1)*box.w,Y=v=>box.y+box.h-(v-min)/(max-min)*box.h;ctx.save();ctx.beginPath();ctx.rect(box.x,box.y,box.w*Math.max(0,Math.min(1,progress)),box.h);ctx.clip();ctx.globalAlpha=alpha;ctx.setLineDash([3,5]);ctx.strokeStyle='#8698b04d';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(box.x,Y(0));ctx.lineTo(box.x+box.w,Y(0));ctx.stroke();ctx.setLineDash([]);ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(X(i),Y(returns[i])):ctx.moveTo(X(i),Y(returns[i])));ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.lineJoin='round';ctx.stroke();ctx.lineTo(box.x+box.w,box.y+box.h);ctx.lineTo(box.x,box.y+box.h);ctx.closePath();const grad=ctx.createLinearGradient(0,box.y,0,box.y+box.h);grad.addColorStop(0,color+'20');grad.addColorStop(1,color+'00');ctx.fillStyle=grad;ctx.fill();ctx.restore()}
function marketPlotCard(ctx,a,k,x,y,w,h,quiet=false){const change=a.points.at(-1)[1]/a.previous-1,color=change>=0?'#5e8a83':'#aa7583';ctx.save();ctx.globalAlpha=quiet?.72:1;ctx.fillStyle=quiet?'#75859a':'#56667c';ctx.font='11px "Lab English","Lab Sans",sans-serif';ctx.textAlign='left';ctx.fillText(marketName(k),x,y+14);ctx.textAlign='right';ctx.font='11px "Lab Numbers",sans-serif';ctx.fillStyle=quiet?'#7b899c':color;ctx.fillText((change>=0?'+':'')+(change*100).toFixed(2)+'%',x+w,y+14);marketDrawLine(ctx,a,{x,y:y+26,w,h:h-52},color,quiet?.55:.85);ctx.textAlign='left';ctx.fillStyle='#8793a5';ctx.font='9px "Lab Numbers","Lab Sans",sans-serif';ctx.fillText(a.date+'  '+a.points[0][0].slice(0,2)+':'+a.points[0][0].slice(2),x,y+h-3);ctx.textAlign='right';ctx.fillText(a.points.at(-1)[0].slice(0,2)+':'+a.points.at(-1)[0].slice(2),x+w,y+h-3);ctx.restore()}
