function marketRender(){const box=$('marketCards');box.innerHTML=MARKET_META.map(([code],k)=>{const a=marketData[k],v=a.points.at(-1)[1],p=v/a.previous-1;return`<article class="market-card"><div class="flex" style="justify-content:space-between"><strong>${marketName(k)}</strong><span class="code">${code}</span></div><div class="market-value">${v.toLocaleString('en-US',{maximumFractionDigits:2})}<span style="color:${p>=0?'#227d75':'#ad647b'}">${p>=0?'+':''}${(p*100).toFixed(2)}%</span></div><div class="market-mini"><canvas id="marketMini${k}" aria-label="${marketName(k)} ${a.date}"></canvas></div><div class="market-meta">${a.date} · ${LANG==='en'?'Trading day':'交易日'}<br>${LANG==='en'?'Quote timestamp':'行情时间'} ${marketEscape(marketClock(a.quoteTime))}<br>${marketFailures.has(code)?(LANG==='en'?'Refresh failed · Last available data':'刷新失败 · 保留最近可用数据'):(LANG==='en'?'Latest successful fetch':'最近成功获取')} ${new Date(a.fetchedAt).toLocaleString(LANG==='en'?'en-GB':'zh-CN',{hour12:false})}</div></article>`}).join('');requestAnimationFrame(()=>{MARKET_META.forEach((_,k)=>{const c=marketCanvas($('marketMini'+k));if(c)marketPlotCard(c.ctx,marketData[k],k,4,2,c.w-8,c.h-4)});marketPaint()});$('marketRefresh').disabled=marketBusy;$('marketRefresh').textContent=marketBusy?'正在刷新…':'↻ 刷新行情';$('marketStatus').textContent=marketFailures.size?'部分连接失败 · 显示最近可用行情':'每60秒自动刷新 · 公开行情可能延迟';}
async function marketRefresh(){if(marketBusy||document.hidden)return;marketBusy=true;marketRender();await Promise.allSettled(MARKET_META.map(async([code],k)=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000),route=code.startsWith('us.')?'UsMinute':'minute';try{const url='https://web.ifzq.gtimg.cn/appstock/app/'+route+'/query?code='+encodeURIComponent(code)+'&_='+Date.now(),res=await fetch(url,{signal:controller.signal,cache:'no-store',credentials:'omit'});if(!res.ok)throw Error('HTTP '+res.status);const next=marketParse(await res.json(),code);if(next.date>=marketData[k].date)marketData[k]=next;marketFailures.delete(code)}catch{marketFailures.add(code)}finally{clearTimeout(timer)}}));marketBusy=false;try{localStorage.setItem('dca-market-v37',JSON.stringify(marketData))}catch{}marketRender()}
function installMarkets(){const dialog=$('marketDialog');let focus=null;function close(){dialog.hidden=true;document.querySelector('main').inert=false;focus?.focus({preventScroll:true})}$('marketBtn').onclick=()=>{focus=document.activeElement;dialog.hidden=false;document.querySelector('main').inert=true;marketRender();$('marketClose').focus()};$('marketClose').onclick=close;dialog.onclick=e=>{if(e.target===dialog)close()};document.addEventListener('keydown',e=>{if(dialog.hidden)return;if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const nodes=[...dialog.querySelectorAll('button:not([disabled]),a[href]')];if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus()}}});$('marketRefresh').onclick=marketRefresh;addEventListener('resize',marketRender);addEventListener('online',marketRefresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden)marketRefresh()});new MutationObserver(marketPaint).observe($('brandIntro'),{attributes:true,attributeFilter:['hidden','class']});let lastMarketLang=LANG;new MutationObserver(()=>{if(lastMarketLang!==LANG){lastMarketLang=LANG;marketRender()}}).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});marketRender();marketRefresh();setInterval(()=>{if(!document.hidden)marketRefresh()},60000)}
